import { n5GrammarPracticeSets } from "./grammar-practice-n5"
import { n4GrammarPracticeSets } from "./grammar-practice-n4"
import { n3GrammarPracticeSets } from "./grammar-practice-n3"
import { n2GrammarPracticeSets } from "./grammar-practice-n2"
import type { GrammarPracticeSet, GrammarPracticeTemplate } from "./grammar-practice-types"

export type { GrammarPracticeSet, GrammarPracticeTemplate } from "./grammar-practice-types"

export interface Example {
  japanese: string;
  romaji: string;
  meaning: string;
}

export type Level = 'N5' | 'N4' | 'N3' | 'N2' | 'N1' | 'Anime'; // Added Anime Level

export interface GrammarPoint {
  id: string;
  title: string;
  structure: string;
  explanation: string;
  examples: Example[];
  level: Level;
  plainExplanation?: string;
  patternParts?: string[];
  pitfalls?: string[];
  practiceTemplates?: GrammarPracticeTemplate[];
  relatedVocabIds?: string[];
  lessonIds?: string[];
  prerequisites?: string[];
}


function grammarPracticeById(sets: GrammarPracticeSet[] | undefined) {
  return new Map((sets ?? []).map((set) => [set.grammarId, set.practiceTemplates]));
}

function withGrammarPractice(points: GrammarPoint[], sets: GrammarPracticeSet[] | undefined): GrammarPoint[] {
  const byId = grammarPracticeById(sets);
  return points.map((point) => ({
    ...point,
    practiceTemplates: byId.get(point.id) ?? point.practiceTemplates,
  }));
}

